class.description:
The ObjCClassWrapper singleton provides a way for the Godot application to send and receive data through the macOS Objective-C system API.
[b]Note:[/b] This singleton is only available in macOS builds.
[codeblock]
var NSColor = ObjCClassWrapper.wrap("NSColor")
var NSColorSpace = ObjCClassWrapper.wrap("NSColorSpace")
var RGBColorSpace = NSColorSpace.genericRGBColorSpace()

var WinColor = NSColor.windowBackgroundColor()
var WinColorRGB = WinColor.colorUsingColorSpace_(RGBColorSpace)

print("color: ", WinColorRGB.redComponent(), " ", WinColorRGB.blueComponent(), " ", WinColorRGB.greenComponent());
[/codeblock]
